package sql

import (
	"context"
	dbsql "database/sql"
	"strings"
)

// identityOverrides lets a seed's rows set the columns PostgreSQL's GENERATED
// ALWAYS and SQL Server's IDENTITY keep for themselves. MySQL, MariaDB and SQLite
// take such a value as they are, and PostgreSQL's GENERATED BY DEFAULT too. Oracle's
// GENERATED ALWAYS has no way to take one, which schemaHint says.
type identityOverrides struct {
	svc *Service
	tx  *dbsql.Tx
	// columns holds each table's identity columns, in lower case.
	columns map[string]map[string]bool
	// on is the table SQL Server has IDENTITY_INSERT on for: a session has one.
	on string
}

func (svc *Service) newIdentityOverrides(tx *dbsql.Tx) *identityOverrides {
	return &identityOverrides{svc: svc, tx: tx, columns: map[string]map[string]bool{}}
}

// prepare readies the database for a row of the table that names those columns,
// and returns what the row's INSERT says between its columns and its values.
func (o *identityOverrides) prepare(ctx context.Context, table string, cols []string) (string, error) {
	d := o.svc.Target.Dialect
	if !d.Postgres && d.Name != sqlserver.Name {
		return "", nil
	}
	names := o.namesIdentity(ctx, table, cols)
	switch {
	case d.Postgres && names:
		return " OVERRIDING SYSTEM VALUE", nil
	case d.Postgres:
		return "", nil
	}
	// SQL Server, once more: on, a row must name the identity column, so rows of
	// a table that do and rows that do not each have it as they need it.
	want := ""
	if names {
		want = table
	}
	if want == o.on {
		return "", nil
	}
	if err := o.close(ctx); err != nil {
		return "", err
	}
	if want != "" {
		if _, err := o.tx.ExecContext(ctx, "SET IDENTITY_INSERT "+want+" ON"); err != nil {
			return "", err
		}
		o.on = want
	}
	return "", nil
}

// namesIdentity says whether the columns include one of the table's identity
// columns. A table the database cannot say anything of has none: the INSERT that
// follows says why.
func (o *identityOverrides) namesIdentity(ctx context.Context, table string, cols []string) bool {
	identity, ok := o.columns[table]
	if !ok {
		identity = map[string]bool{}
		for _, name := range o.svc.names(ctx, o.svc.identityQuery(table)) {
			identity[strings.ToLower(name)] = true
		}
		o.columns[table] = identity
	}
	for _, c := range cols {
		if identity[strings.ToLower(c)] {
			return true
		}
	}
	return false
}

// close turns SQL Server's IDENTITY_INSERT off, which outlives the transaction:
// the connection goes back to the pool.
func (o *identityOverrides) close(ctx context.Context) error {
	if o.on == "" {
		return nil
	}
	table := o.on
	o.on = ""
	_, err := o.tx.ExecContext(context.WithoutCancel(ctx), "SET IDENTITY_INSERT "+table+" OFF")
	return err
}

// identityQuery lists the identity columns of a table a value cannot be given to
// by a plain INSERT. Both catalogs resolve the name as an INSERT does.
func (svc *Service) identityQuery(table string) string {
	d := svc.Target.Dialect
	if d.Postgres {
		return "SELECT attname FROM pg_attribute WHERE attrelid = to_regclass(" + d.Literal(table) + ") AND attidentity = 'a' AND NOT attisdropped"
	}
	return "SELECT name FROM sys.identity_columns WHERE object_id = OBJECT_ID(" + d.Literal(table) + ")"
}
